import json
from pathlib import Path
s=[('ward','The Wardian case: A history of plant transportation','Philippa Lewis · Kew','2016','Европа','https://www.kew.org/read-and-watch/the-wardian-case-a-history-of-plant-transportation'),('palm','Palm House','Royal Botanic Gardens, Kew','б. д.','Европа','https://www.kew.org/kew-gardens/whats-in-the-gardens/palm-house'),('china','Chinese Gardens: Pavilions, Studios, Retreats','The Metropolitan Museum of Art','2012','Азия','https://www.metmuseum.org/exhibitions/listings/2012/chinese-gardens'),('bonsai','National Bonsai & Penjing Museum','U.S. National Arboretum','б. д.','Азия','https://usna.usda.gov/discover/gardens-collections/national-bonsai-penjing-museum/')]
sources=[dict(zip(['id','title','author','year','region','url'],r)) for r in s]
rows=[
('garden-room','От сада к комнате','История','Мир','Все эпохи','Как различать садовую культуру и жизнь растения в интерьере.',['Растение рядом с человеком','Горшок ещё не означает комнату','Как читать свидетельства'],['История комнатного цветоводства находится на пересечении ботаники, архитектуры и истории повседневности. Сад при жилище, переносной контейнер и постоянное содержание растения в помещении — разные практики.','Китайские сады были продолжением жилого пространства. Это не превращает их в комнатные коллекции: материалы Метрополитен-музея рассматривают связи сада с архитектурой и искусством.','У каждого свидетельства важно уточнять место содержания растения, сезон и назначение. Изображение сосуда с растением само по себе не доказывает круглогодичного выращивания в комнате.'],['china']),
('china','Китай: пейзаж в миниатюре','Азия','Китай','Традиционные практики','Сад как продолжение дома и искусство большого мира в малом.',['Сад и жилое пространство','Пэньцзин','Границы сравнения'],['В китайской культуре сад связывает архитектуру с образом природного ландшафта. Выставка Метрополитен-музея раскрывает его связи с литературой и живописью.','Пэньцзин использует древесные растения в контейнерах для живых композиций. Национальный дендрарий США рассматривает пэньцзин и бонсай как самостоятельные искусства.','Контейнерная культура не тождественна комнатному содержанию. Дата появления именно комнатной практики в этом обзоре не установлена.'],['china','bonsai']),
('japan','Япония: искусство бонсай','Азия','Япония','Традиционные практики','Живое дерево, время и внимательное наблюдение за природой.',['Живая композиция','Международный обмен','Условия содержания'],['Бонсай — искусство выращивания и формирования древесных растений в контейнерах. Композиции передают характер дерева в природе и меняются с сезонами.','В 1976 году Япония подарила США 53 дерева бонсай. Дар стал началом коллекции Национального музея бонсай и пэньцзин в Вашингтоне.','Бонсай нельзя автоматически считать комнатным растением: условия зависят от вида. История искусства и история содержания в помещении требуют разных свидетельств.'],['bonsai']),
('wardian-case','Ящик Уорда: путешествие под стеклом','Европа','Великобритания','XIX век','Стеклянная конструкция и большая история путешествий растений.',['Наблюдение 1829 года','Микроклимат в пути','Транспорт и обмен'],['По материалам архива Кью, в 1829 году врач и любитель ботаники Натаниэл Бэгшоу Уорд заметил папоротник, выросший в стеклянном сосуде с коконом мотылька.','Закрытый объём поддерживал более устойчивую влажность. Наблюдение легло в основу конструкции для перевозки растений.','Ящик Уорда показывает роль транспорта в обмене живыми коллекциями. Эту историю следует отделять от торговли срезанными цветами и луковицами: это другие товары и условия доставки.'],['ward']),
('palm-house','Оранжерея как новый мир','Европа','Великобритания','XIX век','Пальмовый дом Кью и архитектура искусственного климата.',['Стекло и металл','1848 год','Коллекция под крышей'],['Оранжерея соединяет архитектуру, отопление, освещение и уход за живой коллекцией. Она создаёт среду для растений за пределами их естественного ареала.','Пальмовый дом Королевских ботанических садов Кью открылся в 1848 году. Это веха истории оранжерей, а не дата возникновения комнатного цветоводства.','Оранжерейное содержание отличается от жилой комнаты управляемым микроклиматом. История таких сооружений помогает понять потребности тропических коллекций.'],['palm']),
('market','Европа и международный цветочный рынок','Европа','Европа','XIX век','Почему история торговли растениями — это ещё и история технологий.',['Разные товары','Живые растения в пути','Открытые вопросы'],['Торговлю луковицами, срезанными цветами и горшечными растениями необходимо рассматривать раздельно: это разные способы хранения и доставки.','Ящик Уорда — пример технологии перевозки живых растений. Материалы Кью позволяют проследить её возникновение.','Роль Нидерландов, питомников и аукционов требует отдельного исследования. Этот вводный обзор не устанавливает дату возникновения международного рынка.'],['ward'])]
a=[dict(zip(['id','title','section','region','era','summary','headings','paragraphs','sources'],r),published=True,type='Редакционный обзор') for r in rows]
d=dict(title='История возникновения комнатного цветоводства',subtitle='От древних садов к растениям на подоконнике',email='',articles=a,sources=sources,events=[dict(year=1829,title='Наблюдение Натаниэла Уорда',region='Европа',type='Технологии',certainty='Документированное событие',article='wardian-case',source='ward'),dict(year=1848,title='Открытие Пальмового дома Кью',region='Европа',type='Оранжереи',certainty='Документированное событие',article='palm-house',source='palm'),dict(year=1976,title='Японский дар: 53 дерева бонсай',region='Азия',type='Коллекции',certainty='Документированное событие',article='japan',source='bonsai')],plants=[dict(id='fern',title='Папоротники',latin='Polypodiopsida',origin='Разные регионы мира; класс, а не отдельный вид',use='Папоротник в сосуде связан с наблюдением Уорда 1829 года.',context='Закрытый стеклянный сосуд',article='wardian-case',source='ward'),dict(id='bonsai',title='Деревья бонсай',latin='Разные древесные виды',origin='Зависит от вида; бонсай — техника выращивания',use='Живые миниатюрные композиции в японской культуре.',context='Контейнерная культура; не обязательно в помещении',article='japan',source='bonsai'),dict(id='palms',title='Пальмы',latin='Arecaceae',origin='Преимущественно тропики и субтропики',use='Оранжерейные коллекции Кью.',context='Оранжерея; семейство, а не отдельный вид',article='palm-house',source='palm')],news=[dict(date='2026-10-16',title='Открыта цифровая коллекция',text='Первые редакционные обзоры, хронология и источники. Рукопись книги и окончательное оглавление ожидают предоставления правообладателем.')])
Path('content/site.json').write_text(json.dumps(d,ensure_ascii=False,indent=2))
